"use client";

import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";
import { useRender } from "@base-ui/react/use-render";
import { cva, type VariantProps } from "class-variance-authority";
import { isValidElement } from "react";
import { cn } from "../lib/cn";
import { useStateColor } from "../lib/css-motion";
import { useMotionHostRef } from "../lib/motion-ref";
import { useCadenceMotion } from "../lib/provider";
import { tabsColourReadable, tabsColourScope } from "../lib/tabs-colour";
import {
  safeTabsPaint,
  TabsDisplayContent,
  TabsListSurface,
  TabsMotionRoot,
  TabsPanelSurface,
  TabsRootSurface,
  useTabsTrigger,
} from "../lib/tabs-motion";

function Tabs({ className, orientation = "horizontal", render, ...props }: TabsPrimitive.Root.Props) {
  return (
    <TabsMotionRoot>
      <TabsPrimitive.Root
        data-slot="tabs"
        data-orientation={orientation}
        orientation={orientation}
        render={(elementProps, state) => <TabsRootSurface elementProps={elementProps} state={state} render={render} />}
        className={(state) =>
          cn(
            "group/tabs flex gap-2 data-[orientation=horizontal]:flex-col",
            typeof className === "function" ? className(state) : className,
          )
        }
        {...props}
      />
    </TabsMotionRoot>
  );
}

const tabsListVariants = cva(
  "group/tabs-list relative isolate inline-flex w-fit items-center justify-center rounded-lg p-[3px] text-muted-foreground group-data-[orientation=horizontal]/tabs:h-9 group-data-[orientation=vertical]/tabs:h-fit group-data-[orientation=vertical]/tabs:flex-col data-[variant=line]:rounded-none",
  {
    variants: { variant: { default: "bg-muted", line: "gap-1 bg-transparent" } },
    defaultVariants: { variant: "default" },
  },
);

function TabsList({
  className,
  variant = "default",
  render,
  ...props
}: TabsPrimitive.List.Props & VariantProps<typeof tabsListVariants>) {
  return (
    <TabsPrimitive.List
      data-variant={variant}
      render={(elementProps, state) => (
        <TabsListSurface
          elementProps={elementProps}
          state={{ ...state, slot: "tabs-list" }}
          render={render}
          variant={variant ?? "default"}
        />
      )}
      className={(state) =>
        cn(tabsListVariants({ variant }), typeof className === "function" ? className(state) : className)
      }
      {...props}
    />
  );
}

// Base UI supplies active state and its merged ref. useRender preserves both forms of caller render.
function TriggerSurface({
  elementProps,
  state,
  render,
  value,
  content,
}: {
  value: unknown;
  content: React.ReactNode;
  elementProps: React.ComponentPropsWithRef<"button">;
  state: TabsPrimitive.Tab.State;
  render: TabsPrimitive.Tab.Props["render"];
}) {
  const { node, ref } = useMotionHostRef(elementProps.ref);
  const cm = useCadenceMotion(node);
  const TriggerPaint = useStateColor(
    ref,
    cm,
    [
      "background-color",
      "color",
      "border-top-color",
      "border-right-color",
      "border-bottom-color",
      "border-left-color",
      "box-shadow",
    ],
    {
      readability: safeTabsPaint(elementProps) ? "verified" : "immediate",
      readabilityGate: tabsColourReadable,
      readabilityScope: tabsColourScope,
    },
  );
  useTabsTrigger(
    node,
    value,
    state.active,
    typeof content === "string" || typeof content === "number" ? content : null,
  );
  return useRender({
    defaultTagName: "button",
    render,
    state: { ...state, slot: "tabs-trigger" },
    stateAttributesMapping: {
      active: () => null,
      disabled: () => null,
      orientation: () => null,
      tabActivationDirection: () => null,
    },
    props: {
      ...elementProps,
      ...TriggerPaint,
      style: { ...TriggerPaint.style, ...elementProps.style },
      "data-slot": "tabs-trigger",
      // A custom component owns its own label/feedback tree (for example Button).
      // Preserve primitive children there instead of disguising them as rich JSX.
      children:
        !render || (isValidElement(render) && typeof render.type === "string") ? (
          <TabsDisplayContent value={elementProps.children} />
        ) : (
          elementProps.children
        ),
    },
  });
}

function TabsTrigger({ className, render, ...props }: TabsPrimitive.Tab.Props) {
  const cm = useCadenceMotion();
  return (
    <TabsPrimitive.Tab
      data-motion={cm.mode}
      className={(state) =>
        cn(
          "after:pointer-events-none after:absolute after:inset-x-0 after:bottom-0 after:h-0.5 after:bg-foreground after:opacity-0 group-data-[orientation=vertical]/tabs:after:inset-y-0 group-data-[orientation=vertical]/tabs:after:right-0 group-data-[orientation=vertical]/tabs:after:left-auto group-data-[orientation=vertical]/tabs:after:w-0.5 group-data-[orientation=vertical]/tabs:after:h-auto group-data-[variant=line]/tabs-list:data-active:after:opacity-100 group-data-[marker-ready]/tabs-list:after:opacity-0 relative isolate inline-flex h-[calc(100%-1px)] flex-1 items-center justify-center gap-1.5 rounded-md border border-transparent px-2 py-1 text-sm font-medium whitespace-nowrap text-muted-foreground group-data-[orientation=vertical]/tabs:w-full group-data-[orientation=vertical]/tabs:justify-start hover:text-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-1 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 aria-disabled:pointer-events-none aria-disabled:opacity-50 data-active:text-foreground data-active:bg-background dark:data-active:bg-input/30 group-data-[marker-ready]/tabs-list:data-active:bg-transparent group-data-[variant=line]/tabs-list:data-active:bg-transparent [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
          typeof className === "function" ? className(state) : className,
        )
      }
      render={(elementProps, state) => (
        <TriggerSurface
          elementProps={elementProps}
          state={state}
          render={render}
          value={props.value}
          content={props.children}
        />
      )}
      {...props}
    />
  );
}

function TabsContent({ className, render, ...props }: TabsPrimitive.Panel.Props) {
  return (
    <TabsPrimitive.Panel
      data-slot="tabs-content"
      render={(elementProps, state) => (
        <TabsPanelSurface
          elementProps={elementProps}
          state={{ ...state, slot: "tabs-content" }}
          render={render}
          value={props.value}
        />
      )}
      className={(state) => cn("flex-1 outline-none", typeof className === "function" ? className(state) : className)}
      {...props}
    />
  );
}

export { Tabs, TabsContent, TabsList, TabsTrigger, tabsListVariants };

"use client";

import type { Tabs as TabsPrimitive } from "@base-ui/react/tabs";
import { useRender } from "@base-ui/react/use-render";
import {
  createContext,
  isValidElement,
  type ReactNode,
  useCallback,
  useContext,
  useInsertionEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { type ContentPaint, createContentTransition } from "./content-transition";
import { useStateColor } from "./css-motion";
import { createMeasuredGeometry, GeometryScope, naturalGeometry } from "./measured-geometry";
import { bindMotionParameters, geometryCompact, layoutCompact, layoutSelection, motionLimits } from "./motion";
import { usePresentationScope } from "./motion-presence";
import { useMotionHostRef } from "./motion-ref";
import { createMotionTransaction, type MotionRevision } from "./motion-transaction";
import { useCadenceMotion } from "./provider";
import { createSelectionProjection, type SelectionBox } from "./selection-projection";
import { tabsColourReadable, tabsColourScope } from "./tabs-colour";
import { createTabsItem, createTabsLayout, type TabsStripSnapshot } from "./tabs-layout";
import { nativeTextContext } from "./text-layout";
import { useNumberPresentation } from "./use-number-presentation";
import { useTextPresentation } from "./use-text-presentation";

function createScope(transaction = createMotionTransaction()) {
  return {
    transaction,
    lists: new Set<() => void>(),
    host: null as HTMLElement | null,
    presented: false,
  };
}
const Root = createContext<ReturnType<typeof createScope> | null>(null);
type Trigger = {
  host: HTMLElement;
  value: unknown;
  active: boolean;
  content: unknown;
  item: ReturnType<typeof createTabsItem>;
};
const List = createContext<Map<object, Trigger> | null>(null);

export function TabsMotionRoot({ children }: { children: ReactNode }) {
  const parent = usePresentationScope();
  const [scope] = useState(() => createScope(parent?.transaction));
  return <Root value={scope}>{children}</Root>;
}

/** Root's committed layout phase follows the primitive's actual selection commit. */
export function TabsRootSurface({
  elementProps,
  state,
  render,
}: {
  elementProps: React.ComponentPropsWithRef<"div">;
  state: TabsPrimitive.Root.State;
  render: TabsPrimitive.Root.Props["render"];
}) {
  const scope = useContext(Root);
  const owner = useMotionHostRef<HTMLDivElement>(elementProps.ref);
  const ref = useCallback(
    (element: HTMLDivElement | null) => {
      if (scope && scope.host !== element) {
        scope.host = element;
        scope.presented = false;
      }
      return owner.ref(element);
    },
    [scope, owner.ref],
  );
  useLayoutEffect(() => {
    for (const flush of scope?.lists ?? []) flush();
    if (scope) scope.presented = true;
  });
  return useRender({ defaultTagName: "div", render, state: { ...state }, props: { ...elementProps, ref } });
}

export function TabsListSurface({
  elementProps,
  state,
  render,
  variant,
}: {
  elementProps: React.ComponentPropsWithRef<"div">;
  state: TabsPrimitive.List.State & { slot?: string };
  render: TabsPrimitive.List.Props["render"];
  variant: string;
}) {
  const scope = useContext(Root);
  const [triggers] = useState(() => new Map<object, Trigger>());
  const { node, ref } = useMotionHostRef(elementProps.ref);
  const strip = useRef<HTMLDivElement>(null);
  const marker = useMotionHostRef<HTMLSpanElement>();
  const cm = useCadenceMotion(node);
  const TrackPaint = useStateColor(
    ref,
    cm,
    ["background-color", "border-top-color", "border-right-color", "border-bottom-color", "border-left-color"],
    {
      readability: safeTabsPaint(elementProps) ? "verified" : "immediate",
      readabilityGate: tabsColourReadable,
      readabilityScope: tabsColourScope,
    },
  );
  const markerCm = useCadenceMotion(marker.node);
  const markerShape = useRef(variant);
  const shapeChanged = markerShape.current !== variant;
  const MarkerPaint = useStateColor(
    marker.ref,
    markerCm,
    [
      "background-color",
      "border-top-color",
      "border-right-color",
      "border-bottom-color",
      "border-left-color",
      "box-shadow",
    ],
    {
      readability: safeTabsPaint(elementProps) ? "verified" : "immediate",
      immediate: shapeChanged,
      readabilityGate: tabsColourReadable,
      readabilityScope: tabsColourScope,
    },
  );
  useLayoutEffect(() => {
    markerShape.current = variant;
  });
  const latest = useRef({ cm, markerCm, variant });
  const configuration = useRef("");
  const connection = useRef<{ dispose(): void; flush(): void } | null>(null);
  const captured = useRef(false);
  const separated = supportsFlowRender(render);
  useLayoutEffect(() => {
    latest.current = { cm, markerCm, variant };
    const shape = `${variant}/${state.orientation}/${separated}`;
    if (configuration.current !== shape) {
      configuration.current = shape;
      connection.current?.dispose();
      connection.current = null;
      if (marker.node.current)
        for (const property of ["left", "top", "width", "height"]) marker.node.current.style.removeProperty(property);
    }
    if (!connection.current && node.current && marker.node.current && scope) {
      const list = node.current;
      const markerNode = marker.node.current;
      const thickness =
        Number.parseFloat(getComputedStyle(markerNode)[state.orientation === "vertical" ? "width" : "height"]) || 0;
      const projection = createSelectionProjection(marker.node, scope.transaction);
      const layout = createTabsLayout(node, marker.node, scope.transaction, triggers);
      let alive = true;
      let observed: HTMLElement | null = null;
      const stamps = new Map<Element, string>();
      let lastRevision: MotionRevision | null = null;
      let cachedBox: SelectionBox | null = null;
      let crossOwned = false;
      let content: string | null = null;
      let lastPolicy = "";
      const identities = new Map<unknown, number>();
      let nextIdentity = 0;
      const identity = (value: unknown) => {
        if (!identities.has(value)) identities.set(value, nextIdentity++);
        return identities.get(value);
      };
      const invalidate = () => {
        if (!alive || node.current !== list) return;
        cachedBox = null;
        projection.invalidate();
        layout.invalidate();
        content = null;
        list.removeAttribute("data-marker-ready");
      };
      const flush = (force = false) => {
        if (!alive || node.current !== list) return;
        const active = [...triggers.values()].filter((record) => record.active && record.host.isConnected);
        const selected = active.length === 1 ? active[0] : null;
        const { cm: policy, markerCm: selectionPolicy, variant: shape } = latest.current;
        const revision = scope.transaction.revision("value", selected?.value ?? null, list);
        for (const value of identities.keys())
          if (![...triggers.values()].some((record) => Object.is(record.value, value))) identities.delete(value);
        const parameters = selectionPolicy.parameters(bindMotionParameters(layoutSelection, "layout.shared/selection"));
        const transition = parameters.kind === "layout" ? parameters.transition : { duration: 0 };
        const geometry = policy.parameters(bindMotionParameters(geometryCompact, "geometry.resize/measured"));
        const reflow = policy.parameters(bindMotionParameters(layoutCompact, "layout.move/position"));
        const sizeClock = geometry.kind === "geometry" ? geometry.transition : { duration: 0 };
        const positionClock = reflow.kind === "layout" ? reflow.transition : { duration: 0 };
        const nextContent = JSON.stringify(
          [...triggers.values()]
            .sort((a, b) => (a.host.compareDocumentPosition(b.host) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1))
            .map((record) => [identity(record.value), record.content]),
        );
        const clock = JSON.stringify([
          policy.mode,
          selectionPolicy.mode,
          selectionPolicy.timeScale,
          sizeClock,
          positionClock,
        ]);
        const policyChanged = clock !== lastPolicy;
        if (lastRevision === revision && content === nextContent && !force && clock === lastPolicy) {
          projection.commit(revision, cachedBox, transition, selectionPolicy.reduced || shape !== "line");
          return;
        }
        const selectionChanged = lastRevision !== revision;
        const knownContent = content !== null && content !== nextContent;
        const wasReflowing = layout.running;
        const origin = layout.prepare();
        const sizeRevision = scope.transaction.revision("content", nextContent, strip);
        content = nextContent;
        lastPolicy = clock;
        lastRevision = revision;
        if (
          !policy.reduced &&
          !selectionPolicy.reduced &&
          shape === "line" &&
          transition.duration !== 0 &&
          !scope.transaction.preflightVisuals(new Set([markerNode]))
        ) {
          invalidate();
          return;
        }
        let box: SelectionBox | null = null;
        let safe = false;
        if (selected && list.getClientRects().length) {
          const target = selected.host;
          if (observed !== target) {
            if (observed) observer.unobserve(observed);
            observed = target;
            observer.observe(target);
          }
          stamps.set(list, `${list.offsetWidth}/${list.offsetHeight}`);
          stamps.set(target, `${target.offsetWidth}/${target.offsetHeight}`);
          const css = getComputedStyle(list),
            paint = getComputedStyle(target);
          const bounds = list.getBoundingClientRect(),
            rect = target.getBoundingClientRect();
          const sx = bounds.width / list.offsetWidth,
            sy = bounds.height / list.offsetHeight;
          safe =
            (target.parentElement === list || target.parentElement === strip.current) &&
            css.position !== "static" &&
            paint.position !== "fixed" &&
            paint.position !== "sticky" &&
            [css, paint].every(
              (style) =>
                style.rotate === "none" &&
                style.scale === "none" &&
                style.translate === "none" &&
                style.transform === "none",
            );
          let ancestor: HTMLElement | null = list;
          for (let depth = 0; ancestor && depth < 32; depth++, ancestor = ancestor.parentElement) {
            const style = getComputedStyle(ancestor);
            const matrix = style.transform === "none" ? null : new DOMMatrixReadOnly(style.transform);
            if (
              style.rotate !== "none" ||
              (style.scale !== "none" &&
                style.scale.split(" ").some((value) => !Number.isFinite(Number(value)) || Number(value) <= 0)) ||
              style.perspective !== "none" ||
              style.offsetPath !== "none" ||
              (matrix && (!matrix.is2D || matrix.b !== 0 || matrix.c !== 0 || matrix.a <= 0 || matrix.d <= 0))
            )
              safe = false;
          }
          if (sx > 0 && sy > 0 && rect.width > 0 && rect.height > 0) {
            box = {
              x:
                (rect.left - bounds.left) / sx +
                list.scrollLeft -
                list.clientLeft +
                Number.parseFloat(paint.borderLeftWidth),
              y:
                (rect.top - bounds.top) / sy +
                list.scrollTop -
                list.clientTop +
                Number.parseFloat(paint.borderTopWidth),
              width:
                rect.width / sx - Number.parseFloat(paint.borderLeftWidth) - Number.parseFloat(paint.borderRightWidth),
              height:
                rect.height / sy - Number.parseFloat(paint.borderTopWidth) - Number.parseFloat(paint.borderBottomWidth),
            };
            if (shape === "line") {
              if (state.orientation === "vertical") {
                box.x += box.width - thickness;
                box.width = thickness;
              } else {
                box.y += box.height - thickness;
                box.height = thickness;
              }
            }
          }
        }
        if (!safe) box = null;
        const natural = strip.current;
        const snapshot = natural ? stripSnapshot(list, natural, [...triggers.values()], box, state.orientation) : null;
        const eligible =
          separated &&
          safe &&
          snapshot &&
          !nativeTextContext(list) &&
          !list.contains(list.ownerDocument.activeElement) &&
          !captured.current &&
          !policy.reduced &&
          !selectionPolicy.reduced &&
          sizeClock.duration !== 0 &&
          positionClock.duration !== 0;
        // Selection and reflow never run separate writers on the marker. A new
        // selection during strip projection settles the entire affected geometry.
        const coordinated = Boolean(eligible && (knownContent || (wasReflowing && policyChanged)) && !selectionChanged);
        crossOwned = coordinated && snapshot?.crossWidth !== undefined;
        if (coordinated || wasReflowing) projection.cancel();
        cachedBox = box;
        projection.commit(
          revision,
          box,
          transition,
          selectionPolicy.reduced || shape !== "line" || !safe || coordinated || wasReflowing,
        );
        layout.commit(sizeRevision, snapshot, sizeClock, positionClock, !coordinated, origin);
        mutations.takeRecords();
        if (alive && node.current === list) list.toggleAttribute("data-marker-ready", Boolean(box));
      };
      const observer = new ResizeObserver((entries) => {
        if (
          entries.some((entry) => {
            const size = entry.borderBoxSize?.[0];
            if (size && entry.target === list && layout.running) {
              if (crossOwned) return false;
              const [width, height] = (stamps.get(list) ?? "").split("/").map(Number);
              if (
                state.orientation === "vertical"
                  ? Math.round(size.inlineSize) === width
                  : Math.round(size.blockSize) === height
              )
                return false;
            }
            return size && `${Math.round(size.inlineSize)}/${Math.round(size.blockSize)}` !== stamps.get(entry.target);
          })
        )
          invalidate();
      });
      observer.observe(list);
      // Content changes are invalidation only, never a synthetic selection.
      const mutations = new MutationObserver((entries) => {
        const withoutClock = (style: string) =>
          style
            .replace(
              /--(?:(?:motion-|ease-cadence-)[\w-]+|cadence-(?:inherited-[\w-]+|time-scale|recipe-enabled))\s*:[^;]*;?/g,
              "",
            )
            .replace(/transition(?:-[\w-]+)?\s*:[^;]*;?/g, "")
            .trim();
        if (
          entries.some(
            (entry) =>
              entry.type === "attributes" &&
              entry.target !== markerNode &&
              (entry.target === list ||
                !list.contains(entry.target) ||
                [...triggers.values()].some((record) => record.host === entry.target)) &&
              !["data-active", "aria-selected"].includes(entry.attributeName ?? "") &&
              (entry.attributeName !== "style" ||
                withoutClock(entry.oldValue ?? "") !== withoutClock((entry.target as HTMLElement).style.cssText)),
          )
        )
          invalidate();
        else if (entries.some((entry) => entry.type === "childList" || entry.type === "characterData")) invalidate();
        // Child text mutations are already consumed in committed content work.
        // Unknown descendants resize through the passive observer, never reflow.
      });
      mutations.observe(list, {
        childList: true,
        subtree: true,
        characterData: true,
        attributes: true,
        attributeOldValue: true,
        attributeFilter: ["class", "style", "hidden", "contenteditable"],
      });
      const view = list.ownerDocument.defaultView;
      let ancestor = list.parentElement;
      for (let depth = 0; ancestor && depth < 32; depth++, ancestor = ancestor.parentElement)
        mutations.observe(ancestor, {
          attributes: true,
          attributeOldValue: true,
          attributeFilter: ["class", "style", "hidden", "contenteditable"],
        });
      view?.addEventListener("resize", invalidate);
      view?.visualViewport?.addEventListener("resize", invalidate);
      list.ownerDocument.fonts?.addEventListener("loadingdone", invalidate);
      scope.lists.add(flush);
      connection.current = {
        flush,
        dispose() {
          alive = false;
          scope.lists.delete(flush);
          projection.dispose();
          layout.dispose();
          observer.disconnect();
          mutations.disconnect();
          view?.removeEventListener("resize", invalidate);
          view?.visualViewport?.removeEventListener("resize", invalidate);
          list.ownerDocument.fonts?.removeEventListener("loadingdone", invalidate);
          list.removeEventListener("focusin", settleLayout);
          list.removeEventListener("pointerdown", capture);
          view?.removeEventListener("pointerup", releaseCapture);
          view?.removeEventListener("pointercancel", releaseCapture);
        },
      };
      const settleLayout = () => {
        layout.invalidate();
      };
      const capture = () => {
        captured.current = true;
        settleLayout();
      };
      const releaseCapture = () => {
        captured.current = false;
      };
      list.addEventListener("focusin", settleLayout);
      list.addEventListener("pointerdown", capture);
      view?.addEventListener("pointerup", releaseCapture);
      view?.addEventListener("pointercancel", releaseCapture);
      node.invalidate = () => {
        const old = connection.current;
        connection.current = null;
        old?.dispose();
      };
    }
    connection.current?.flush();
  });
  useInsertionEffect(
    () => () => {
      const old = connection.current;
      connection.current = null;
      old?.dispose();
    },
    [],
  );
  return (
    <List value={triggers}>
      {useRender({
        defaultTagName: "div",
        render,
        state: { ...state },
        props: {
          ...elementProps,
          ...TrackPaint,
          style: { ...TrackPaint.style, ...elementProps.style },
          "data-slot": "tabs-list",
          children: (
            <>
              {!separated ? (
                elementProps.children
              ) : (
                <div
                  ref={strip}
                  data-slot="tabs-strip"
                  className="inline-flex h-full min-w-0 flex-1 items-center justify-center gap-inherit [gap:inherit] group-data-[orientation=vertical]/tabs:flex-col"
                >
                  {elementProps.children}
                </div>
              )}
              <span
                {...MarkerPaint}
                aria-hidden="true"
                hidden
                data-slot="tabs-indicator"
                data-motion={markerCm.mode}
                className="pointer-events-none absolute top-0 left-0 -z-10 origin-top-left rounded-md bg-background shadow-sm dark:bg-input/30 data-[variant=line]:rounded-none data-[variant=line]:bg-foreground data-[variant=line]:shadow-none data-[variant=line]:h-0.5 data-[orientation=vertical]:data-[variant=line]:h-auto data-[orientation=vertical]:data-[variant=line]:w-0.5"
                data-variant={variant}
                data-orientation={state.orientation as string}
              />
            </>
          ),
        },
      })}
    </List>
  );
}

export function useTabsTrigger(
  node: React.RefObject<HTMLElement | null>,
  value: unknown,
  active: boolean,
  content: unknown,
) {
  const list = useContext(List);
  const scope = useContext(Root);
  const cm = useCadenceMotion(node);
  const connected = useRef<{ host: HTMLElement; item: ReturnType<typeof createTabsItem> } | null>(null);
  const [identity] = useState(() => ({}));
  useLayoutEffect(() => {
    const host = node.current;
    if (connected.current?.host !== host) {
      connected.current?.item.dispose();
      connected.current = null;
    }
    if (host && scope) {
      if (!connected.current) connected.current = { host, item: createTabsItem(node, scope.transaction) };
      const parameters = cm.parameters(bindMotionParameters(layoutCompact, "layout.move/position"));
      if (parameters.kind === "layout")
        connected.current.item.commit(
          scope.transaction.revision("content", content, node),
          parameters.transition,
          cm.reduced,
        );
      list?.set(identity, { host, value, active, content, item: connected.current.item });
    }
  });
  useInsertionEffect(
    () => () => {
      list?.delete(identity);
      connected.current?.item.dispose();
      connected.current = null;
    },
    [list, identity],
  );
}

export function TabsPanelSurface({
  elementProps,
  state,
  render,
  value,
}: {
  elementProps: React.ComponentPropsWithRef<"div">;
  state: TabsPrimitive.Panel.State & { slot?: string };
  render: TabsPrimitive.Panel.Props["render"];
  value: unknown;
}) {
  const scope = useContext(Root);
  const parent = usePresentationScope();
  const { node, ref } = useMotionHostRef(elementProps.ref);
  const cm = useCadenceMotion(node);
  const [paint] = useState(() => createContentTransition(scope?.transaction));
  const flow = useRef<HTMLDivElement>(null);
  const separated = supportsFlowRender(render);
  const geometrySource = useRef({});
  const valueRevision = useRef({ value, revision: 0 });
  const parentGeometry = useContext(GeometryScope);
  const [geometry] = useState(() => createMeasuredGeometry(scope?.transaction));
  const group = parentGeometry?.controller ?? geometry;
  const connected = useRef<{ host: HTMLElement; content: HTMLElement; group: typeof group; release(): void } | null>(
    null,
  );
  const previous = useRef<boolean | null>(null);
  const cached = useRef<{ revision: MotionRevision; participant: ContentPaint } | null>(null);
  useLayoutEffect(() => {
    const visible = !state.hidden;
    const changed = previous.current === false && visible;
    previous.current = visible;
    const revision = scope?.transaction.revision("content", visible ? value : null, node);
    if (!visible) paint.cancel();
    if (revision) {
      let available = visible && (parent?.available() ?? true) && (changed || Boolean(scope?.presented));
      if (cached.current?.revision === revision) {
        paint.commit(revision, [cached.current.participant], cm, false, available);
        return;
      }
      const direction = /left|up/.test(state.tabActivationDirection)
        ? -1
        : /right|down/.test(state.tabActivationDirection)
          ? 1
          : 0;
      const participant: ContentPaint = {
        host: node,
        direction,
        axis: /up|down/.test(state.tabActivationDirection) ? "y" : "x",
        travel: false,
      };
      const panel = node.current;
      if (panel && nativeTextContext(panel)) available = false;
      const root = panel?.parentElement;
      if (
        available &&
        panel &&
        cm.transition("data.transition").duration !== 0 &&
        scope &&
        !scope.transaction.preflightVisuals(new Set([panel]))
      )
        available = false;
      if (available && panel && root && direction && root.getAttribute("data-slot") === "tabs" && !cm.reduced) {
        participant.travel = paint.canTravel(root, node, participant.axis ?? "x", direction, cm.distance.xs);
      }
      // Arbitrary panels without an existing paint corridor keep native size
      // and incoming opacity. No duplicate tree or forced viewport is made.
      cached.current = { revision, participant };
      paint.commit(revision, [participant], cm, false, available);
    }
  });
  useLayoutEffect(() => {
    const host = node.current;
    const content = separated ? flow.current : host;
    if (
      connected.current &&
      (connected.current.host !== host || connected.current.content !== content || connected.current.group !== group)
    ) {
      connected.current.release();
      connected.current = null;
    }
    if (host && content && !connected.current) {
      const release = group.register({
        host: node,
        content,
        axes: ["height"],
        observeChildren: true,
        measure() {
          if (host.hidden || nativeTextContext(host)) return null;
          const outer = naturalGeometry(host),
            inner = naturalGeometry(content);
          if (!outer || !inner) return null;
          const css = getComputedStyle(host);
          const family = css.transitionProperty.split(",").map((value) => value.trim()),
            clocks = css.transitionDuration.split(",").map(Number.parseFloat);
          const geometry = ["all", "width", "height", "flex", "flex-basis", "flex-grow", "flex-shrink"];
          if (
            family.some((property, index) => geometry.includes(property) && (clocks[index % clocks.length] ?? 0) > 0) ||
            host
              .getAnimations()
              .some((animation) =>
                (animation.effect as KeyframeEffect | null)
                  ?.getKeyframes()
                  .some((frame) =>
                    ["width", "height", "flexBasis", "flexGrow", "flexShrink"].some((property) => property in frame),
                  ),
              )
          )
            return null;
          const intrinsic = host.computedStyleMap?.().get("height")?.toString();
          if (intrinsic && !["auto", "fit-content", "max-content"].includes(intrinsic)) return null;
          if (css.aspectRatio !== "auto" || css.writingMode !== "horizontal-tb") return null;
          // No clone, inactive measurement or cross-panel height source. The
          // original content lays out at destination width, with visible overflow.
          const size =
            content === host
              ? outer.height
              : inner.height +
                (css.boxSizing === "border-box"
                  ? Number.parseFloat(css.paddingTop) +
                    Number.parseFloat(css.paddingBottom) +
                    Number.parseFloat(css.borderTopWidth) +
                    Number.parseFloat(css.borderBottomWidth)
                  : 0);
          const parentStyle = host.parentElement ? getComputedStyle(host.parentElement) : null;
          const intrinsicMinimum =
            css.minHeight === "auto" &&
            (parentStyle?.display.includes("grid") ||
              (parentStyle?.display.includes("flex") && parentStyle.flexDirection.startsWith("column")));
          return {
            height: {
              size,
              min: css.overflowY === "visible" && !intrinsicMinimum ? 0 : size,
              flexBlock: Boolean(
                parentStyle?.display.includes("flex") &&
                  parentStyle.flexDirection.startsWith("column") &&
                  ["auto", "fit-content", "max-content"].includes(
                    host.parentElement?.computedStyleMap?.().get("height")?.toString() ?? "",
                  ) &&
                  !host.style.flex &&
                  !host.style.flexBasis &&
                  !host.style.flexGrow &&
                  !host.style.flexShrink,
              ),
              independent: true,
              readable: content !== host,
            },
          };
        },
      });
      connected.current = {
        host,
        content,
        group,
        release() {
          editing.disconnect();
          host.ownerDocument.removeEventListener("selectionchange", select);
          release();
        },
      };
      const settleEditing = () => {
        if (nativeTextContext(host)) {
          group.settle();
          paint.cancel();
        }
      };
      const editing = new MutationObserver(settleEditing);
      let ancestor: HTMLElement | null = host;
      for (
        let depth = 0;
        ancestor && depth < motionLimits.collectionVisuals;
        depth++, ancestor = ancestor.parentElement
      )
        editing.observe(ancestor, { attributes: true, attributeFilter: ["contenteditable"] });
      const select = () => {
        const anchor = host.ownerDocument.getSelection()?.anchorNode;
        if (anchor && host.contains(anchor)) {
          group.settle();
          paint.cancel();
        }
      };
      host.ownerDocument.addEventListener("selectionchange", select);
    }
    const parameters = cm.parameters(bindMotionParameters(geometryCompact, "geometry.resize/measured"));
    if (!Object.is(valueRevision.current.value, value))
      valueRevision.current = { value, revision: valueRevision.current.revision + 1 };
    if (parentGeometry) parentGeometry.request?.();
    else if (scope && parameters.kind === "geometry")
      geometry.commit(
        scope.transaction.revision(
          "content",
          JSON.stringify([
            valueRevision.current.revision,
            state.hidden,
            host?.textContent,
            elementProps.className,
            elementProps.style,
            flow.current?.childElementCount,
          ]),
          geometrySource.current,
        ),
        {
          reduced: cm.reduced,
          transition: parameters.transition,
          available: !state.hidden && (parent?.available() ?? true),
        },
      );
  });
  useInsertionEffect(
    () => () => {
      connected.current?.release();
      connected.current = null;
      geometry.settle();
    },
    [geometry],
  );
  useInsertionEffect(() => () => paint.cancel(), [paint]);
  const children = (
    <TabsDisplayContent value={elementProps.children} visible={!state.hidden && previous.current === true} />
  );
  return useRender({
    defaultTagName: "div",
    render,
    state: { ...state },
    props: {
      ...elementProps,
      ref,
      "data-motion": cm.mode,
      children: !separated ? (
        children
      ) : (
        <div ref={flow} data-slot="tabs-panel-flow" className="flow-root min-w-0">
          {children}
        </div>
      ),
    },
  });
}

/** Default semantic palettes; custom paint retains its exact immediate cascade. */
export function safeTabsPaint(props: { className?: string; style?: React.CSSProperties }) {
  if (
    Object.keys(props.style ?? {}).some((key) =>
      /color|background|shadow|opacity|filter|blend|^--(?!motion-|cadence-|ease-)/i.test(key),
    )
  )
    return false;
  return !(props.className ?? "").split(/\s+/).some((token) => {
    const name = token.split(":").pop() ?? "";
    return (
      /^(bg-|text-|border-|shadow-)/.test(name) &&
      !/^(?:bg-(?:muted|background|foreground|transparent|input\/30)|text-(?:muted-foreground|foreground|sm|xs|base|lg|xl)|border-(?:transparent|ring)|shadow-(?:sm|none))$/.test(
        name,
      )
    );
  });
}

function supportsFlowRender(render: unknown) {
  return (
    !render ||
    (isValidElement(render) &&
      typeof render.type === "string" &&
      ["div", "section", "article", "nav"].includes(render.type))
  );
}

export function TabsDisplayContent({ value, visible = true }: { value: ReactNode; visible?: boolean }) {
  return typeof value === "string" || typeof value === "number" ? (
    <TabsDisplay value={value} visible={visible} />
  ) : (
    value
  );
}

function TabsDisplay({ value, visible }: { value: string | number; visible: boolean }) {
  const { node, ref } = useMotionHostRef<HTMLSpanElement>();
  const cm = useCadenceMotion(node);
  const scope = useContext(Root);
  const [entity] = useState(() => ({}));
  const initial = useRef(String(value)),
    previous = useRef(String(value));
  const isText = typeof value === "string";
  const text = useTextPresentation(
    node,
    isText ? value : "",
    cm,
    entity,
    {
      characterStagger: false,
      visible,
      enabled: isText,
      initialText: initial.current,
      nativeBaseline: previous.current,
    },
    scope?.transaction,
  );
  const number = useNumberPresentation(
    node,
    isText ? 0 : value,
    cm,
    entity,
    {
      compact: true,
      cause: "independent",
      visible,
      enabled: !isText,
      retainEditedContent: true,
      initialText: initial.current,
      nativeBaseline: previous.current,
    },
    scope?.transaction,
  );
  useLayoutEffect(() => {
    previous.current = String(value);
  });
  return isText ? (
    <span ref={ref} data-slot="tabs-text" data-motion={cm.mode}>
      {text}
    </span>
  ) : (
    <span ref={ref} data-slot="tabs-number" data-motion={cm.mode}>
      {number}
    </span>
  );
}

function stripSnapshot(
  list: HTMLElement,
  strip: HTMLElement,
  records: Trigger[],
  marker: SelectionBox | null,
  orientation: string,
): TabsStripSnapshot | null {
  if (
    records.length > motionLimits.collectionVisuals ||
    !list.getClientRects().length ||
    !strip.getClientRects().length
  )
    return null;
  const css = getComputedStyle(list),
    bounds = list.getBoundingClientRect();
  const axis = orientation === "vertical" ? "height" : "width";
  const intrinsic = list.computedStyleMap?.().get(axis)?.toString();
  if (
    !intrinsic ||
    !["auto", "fit-content", "max-content"].includes(intrinsic) ||
    css.writingMode !== "horizontal-tb" ||
    css.aspectRatio !== "auto"
  )
    return null;
  const native = naturalGeometry(list);
  if (!native) return null;
  const properties = css.transitionProperty.split(",").map((value) => value.trim());
  const durations = css.transitionDuration.split(",").map(Number.parseFloat);
  if (
    properties.some(
      (property, index) =>
        ["all", "width", "height", "transform", "translate", "scale", "rotate"].includes(property) &&
        (durations[index % durations.length] ?? 0) > 0,
    ) ||
    list
      .getAnimations()
      .some((a) =>
        (a.effect as KeyframeEffect | null)
          ?.getKeyframes()
          .some((frame) => ["width", "height", "transform", "translate", "scale", "rotate"].some((p) => p in frame)),
      )
  )
    return null;
  const sx = bounds.width / list.offsetWidth,
    sy = bounds.height / list.offsetHeight;
  if (!(sx > 0 && sy > 0)) return null;
  const items = new Map<HTMLElement, SelectionBox>();
  for (const { host } of records) {
    if (host.parentElement !== strip || !host.getClientRects().length) return null;
    const paint = getComputedStyle(host);
    if (
      [paint, css].some(
        (s) =>
          s.transform !== "none" ||
          s.translate !== "none" ||
          s.scale !== "none" ||
          s.rotate !== "none" ||
          /fixed|sticky/.test(s.position),
      )
    )
      return null;
    if (
      host
        .getAnimations()
        .some((a) =>
          (a.effect as KeyframeEffect | null)
            ?.getKeyframes()
            .some((f) => ["transform", "translate", "scale", "rotate"].some((p) => p in f)),
        )
    )
      return null;
    const rect = host.getBoundingClientRect();
    items.set(host, {
      x: (rect.left - bounds.left) / sx + list.scrollLeft - list.clientLeft,
      y: (rect.top - bounds.top) / sy + list.scrollTop - list.clientTop,
      width: rect.width / sx,
      height: rect.height / sy,
    });
  }
  return {
    axis,
    size: native[axis],
    items,
    marker,
    strip,
    inlineSize: strip.getBoundingClientRect().width / sx,
    blockSize: strip.getBoundingClientRect().height / sy,
    selected: records.find((record) => record.active)?.host,
    crossWidth:
      orientation === "vertical" &&
      ["auto", "fit-content", "max-content"].includes(list.computedStyleMap?.().get("width")?.toString() ?? "")
        ? native.width
        : undefined,
    clipped: (axis === "width" ? css.overflowX : css.overflowY) !== "visible",
  };
}

"use client";

import { animateSingleValue, motionValue, type Transition } from "motion/react";
import { motionLimits } from "./motion";
import { subscribeMotionEnvironment } from "./motion-environment";
import type { MotionHostRef } from "./motion-ref";
import { createMotionTransaction, type MotionLease, type MotionRevision } from "./motion-transaction";
import type { SelectionBox } from "./selection-projection";

export type TabsStripSnapshot = {
  size: number;
  axis: "width" | "height";
  items: Map<HTMLElement, SelectionBox>;
  marker: SelectionBox | null;
  strip: HTMLElement;
  inlineSize: number;
  blockSize: number;
  velocity?: number;
  crossWidth?: number;
  selected?: HTMLElement;
  clipped?: boolean;
  velocities?: Map<HTMLElement, { x: number; y: number }>;
};

/** A trigger owns its transform; the list supplies its one shared projection. */
export function createTabsItem(host: MotionHostRef<HTMLElement>, transaction = createMotionTransaction()) {
  const node = host.current;
  if (!node) throw new Error("Tabs item requires its committed trigger");
  const identity = host.identity,
    owner = transaction.register(node);
  let revision: MotionRevision | null = null,
    immediate = true;
  let clock = "";
  let effect: Animation | null = null,
    lease: MotionLease | null = null;
  const cancel = () => {
    effect?.cancel();
    effect = null;
    const old = lease;
    lease = null;
    old?.cancel();
  };
  return {
    commit(next: MotionRevision, transition: Transition, instant: boolean) {
      revision = next;
      clock = JSON.stringify(transition);
      immediate = instant || transition.duration === 0;
      if (immediate) cancel();
    },
    compatible(transition: Transition) {
      return !immediate && clock === JSON.stringify(transition);
    },
    project(visuals: Set<HTMLElement>) {
      cancel();
      if (immediate || !revision?.current() || node !== host.current || identity !== host.identity || !node.animate)
        return false;
      lease = owner.begin(revision, ["transform"], { collectionVisuals: visuals }, cancel);
      if (!lease) return false;
      effect = node.animate({}, { duration: 0, fill: "both" });
      return true;
    },
    write(x: number, y: number) {
      if (lease?.current() && effect && node === host.current && identity === host.identity)
        (effect.effect as KeyframeEffect | null)?.setKeyframes({ transform: `translate(${x}px,${y}px)` });
    },
    cancel,
    dispose() {
      cancel();
      owner.dispose();
    },
  };
}

/** One clamped projection for strip extent, retained positions and marker attachment.
 * Natural endpoints are read by the adapter after releasing these overlays.
 * A concurrent selection cannot borrow this clock: that transaction settles as a unit.
 */
export function createTabsLayout(
  host: MotionHostRef<HTMLElement>,
  marker: MotionHostRef<HTMLElement>,
  transaction = createMotionTransaction(),
  registrations: ReadonlyMap<object, { host: HTMLElement; item: ReturnType<typeof createTabsItem> }> = new Map(),
) {
  const phase = motionValue(1);
  const extent = motionValue(0);
  const cross = motionValue(0);
  let previous: MotionRevision | null = null;
  let baseline: TabsStripSnapshot | null = null;
  let path: { from: TabsStripSnapshot; to: TabsStripSnapshot } | null = null;
  let alive = true;
  let restricted = false;
  let signature = "";
  const effects = new Map<HTMLElement, Animation>();
  const leases: MotionLease[] = [];
  const owners: ReturnType<typeof transaction.register>[] = [];
  const progress = () => Math.max(0, Math.min(1, phase.get()));
  const interpolate = (a: number, b: number) => a + (b - a) * progress();
  const box = (a: SelectionBox, b: SelectionBox): SelectionBox => ({
    x: interpolate(a.x, b.x),
    y: interpolate(a.y, b.y),
    width: interpolate(a.width, b.width),
    height: interpolate(a.height, b.height),
  });
  const sample = (): TabsStripSnapshot | null =>
    path
      ? {
          size: Math.max(
            Math.min(path.from.size, path.to.size),
            Math.min(Math.max(path.from.size, path.to.size), extent.get()),
          ),
          axis: path.to.axis,
          items: new Map(
            [...path.to.items].map(([node, target]) => [node, box(path?.from.items.get(node) ?? target, target)]),
          ),
          marker:
            path.to.marker && path.to.selected && path.to.items.get(path.to.selected)
              ? (() => {
                  const target = path.to.items.get(path.to.selected),
                    before = path.from.items.get(path.to.selected);
                  if (!target) return path.to.marker;
                  const item = box(before ?? target, target);
                  return {
                    ...path.to.marker,
                    x: item.x + path.to.marker.x - target.x,
                    y: item.y + path.to.marker.y - target.y,
                  };
                })()
              : path.to.marker,
          strip: path.to.strip,
          inlineSize: path.to.inlineSize,
          blockSize: path.to.blockSize,
          velocity: extent.getVelocity(),
          velocities: new Map(
            [...path.to.items].map(([node, target]) => {
              const before = path?.from.items.get(node) ?? target;
              return [
                node,
                { x: (target.x - before.x) * phase.getVelocity(), y: (target.y - before.y) * phase.getVelocity() },
              ];
            }),
          ),
          crossWidth:
            path.to.crossWidth === undefined
              ? undefined
              : Math.max(
                  Math.min(path.from.crossWidth ?? path.to.crossWidth, path.to.crossWidth),
                  Math.min(Math.max(path.from.crossWidth ?? path.to.crossWidth, path.to.crossWidth), cross.get()),
                ),
          selected: path.to.selected,
        }
      : baseline;
  const cancel = () => {
    phase.stop();
    extent.stop();
    cross.stop();
    path = null;
    for (const effect of effects.values()) effect.cancel();
    effects.clear();
    for (const lease of leases.splice(0)) lease.cancel();
    for (const owner of owners.splice(0)) owner.dispose();
    for (const { item } of registrations.values()) item.cancel();
  };
  const write = () => {
    if (!alive || !path || leases.some((lease) => !lease.current())) return;
    const current = sample();
    if (!current) return;
    for (const { host: node, item } of registrations.values()) {
      const target = path.to.items.get(node),
        position = current.items.get(node);
      if (target && position) item.write(position.x - target.x, position.y - target.y);
    }
    for (const [node, effect] of effects) {
      const target = path.to.items.get(node),
        position = current.items.get(node);
      const frame =
        node === host.current
          ? {
              [current.axis]: `${current.size}px`,
              ...(current.crossWidth === undefined ? {} : { width: `${current.crossWidth}px` }),
              justifyContent: "flex-start",
            }
          : node === current.strip
            ? {
                width: `${current.inlineSize}px`,
                minWidth: `${current.inlineSize}px`,
                maxWidth: `${current.inlineSize}px`,
                flex: "none",
                ...(current.axis === "height"
                  ? {
                      height: `${current.blockSize}px`,
                      minHeight: `${current.blockSize}px`,
                      maxHeight: `${current.blockSize}px`,
                    }
                  : {}),
              }
            : node === marker.current && current.marker && path.to.marker
              ? {
                  transform: `translate(${current.marker.x - path.to.marker.x}px,${current.marker.y - path.to.marker.y}px) scale(${current.marker.width / path.to.marker.width},${current.marker.height / path.to.marker.height})`,
                }
              : target && position
                ? { transform: `translate(${position.x - target.x}px,${position.y - target.y}px)` }
                : {};
      (effect.effect as KeyframeEffect | null)?.setKeyframes(frame);
    }
  };
  const off = phase.on("change", write);
  const offSize = extent.on("change", write);
  const offCross = cross.on("change", write);
  const unsubscribe = host.current
    ? subscribeMotionEnvironment(host.current.ownerDocument, (environment) => {
        restricted = environment.hidden || environment.reduced || environment.immediate;
        if (restricted) {
          cancel();
          baseline = null;
        }
      })
    : () => {};
  return {
    get running() {
      return path !== null;
    },
    /** Capture current projection without layout reads, then reveal native layout. */
    prepare() {
      const current = sample();
      cancel();
      return current;
    },
    commit(
      revision: MotionRevision,
      destination: TabsStripSnapshot | null,
      transition: Transition,
      positionTransition: Transition,
      immediate: boolean,
      origin: TabsStripSnapshot | null = baseline,
    ) {
      const clock = JSON.stringify([transition, positionTransition]);
      const same = revision === previous;
      previous = revision;
      const retime = signature !== clock;
      signature = clock;
      baseline = destination;
      // Native labels use their final width throughout. Prove that the starting
      // positions leave room for those exact labels; otherwise only the strip's
      // safe empty-space size can interpolate, with affected positions immediate.
      if (origin && destination) {
        const start = origin;
        const axis = destination.axis === "height" ? "y" : "x",
          extent = axis === "x" ? "width" : "height";
        const order = [...destination.items].sort((a, b) => a[1][axis] - b[1][axis]);
        const overlaps = order.some(([node, target], index) => {
          const next = order[index + 1];
          if (!next) return false;
          return (start.items.get(node) ?? target)[axis] + target[extent] > (start.items.get(next[0]) ?? next[1])[axis];
        });
        if (overlaps)
          origin = { ...destination, size: origin.size, crossWidth: origin.crossWidth, velocity: origin.velocity };
        if (destination.clipped && origin.size < destination.size) origin = { ...origin, size: destination.size };
      }
      const unchanged =
        origin &&
        destination &&
        origin.size === destination.size &&
        origin.crossWidth === destination.crossWidth &&
        origin.items.size === destination.items.size &&
        [...destination.items].every(([node, target]) => {
          const before = origin.items.get(node);
          return (
            before &&
            ["x", "y", "width", "height"].every(
              (key) => before[key as keyof SelectionBox] === target[key as keyof SelectionBox],
            )
          );
        });
      if (
        unchanged ||
        !alive ||
        !destination ||
        !origin ||
        registrations.size > motionLimits.collectionVisuals ||
        [...registrations.values()].some(({ host: item }) => !item.isConnected || !host.current?.contains(item)) ||
        origin.axis !== destination.axis ||
        (same && !retime) ||
        immediate ||
        restricted ||
        transition.duration === 0 ||
        positionTransition.duration === 0 ||
        [...registrations.values()].some(({ item }) => !item.compatible(positionTransition)) ||
        !host.current?.animate ||
        !revision.current() ||
        !Number.isFinite(destination.size) ||
        destination.size <= 0
      )
        return;
      const rates: number[] = [];
      for (const [node, target] of destination.items) {
        const before = origin.items.get(node) ?? target,
          velocity = origin.velocities?.get(node);
        for (const axis of ["x", "y"] as const)
          if (target[axis] !== before[axis]) rates.push((velocity?.[axis] ?? 0) / (target[axis] - before[axis]));
      }
      const rate = rates[0] ?? 0;
      const coherent = rates.every(
        (value) => Math.abs(value - rate) <= Number.EPSILON * Math.max(1, Math.abs(value), Math.abs(rate)),
      );
      const nodes = new Set([
        host.current,
        destination.strip,
        ...destination.items.keys(),
        ...(destination.marker && marker.current ? [marker.current] : []),
      ]);
      if (!transaction.preflightVisuals(nodes)) return;
      const add = (node: HTMLElement, properties: string[]) => {
        const owner = transaction.register(node);
        owners.push(owner);
        const lease = owner.begin(revision, properties, { collectionVisuals: nodes }, cancel);
        if (!lease) return false;
        leases.push(lease);
        effects.set(node, node.animate({}, { duration: 0, fill: "both" }));
        return true;
      };
      if (!add(host.current, [destination.axis])) {
        cancel();
        return;
      }
      if (!add(destination.strip, ["width", "min-width", "max-width", "flex"])) {
        cancel();
        return;
      }
      for (const { item } of registrations.values())
        if (!item.project(nodes)) {
          cancel();
          return;
        }
      if (destination.marker && marker.current && !add(marker.current, ["transform"])) {
        cancel();
        return;
      }
      phase.jump(0);
      extent.jump(origin.size);
      cross.jump(origin.crossWidth ?? destination.crossWidth ?? 0);
      path = { from: origin, to: destination };
      write();
      let pending = destination.crossWidth === undefined ? 2 : 3;
      const complete = () => {
        if (!--pending) cancel();
      };
      animateSingleValue(extent, destination.size, {
        ...transition,
        velocity: origin.velocity ?? 0,
        onComplete: complete,
      });
      animateSingleValue(phase, 1, {
        ...positionTransition,
        velocity: coherent ? Math.max(0, rate) : 0,
        onComplete: complete,
      });
      if (destination.crossWidth !== undefined)
        animateSingleValue(cross, destination.crossWidth, { ...transition, onComplete: complete });
    },
    invalidate() {
      cancel();
      baseline = null;
    },
    dispose() {
      alive = false;
      cancel();
      off();
      offSize();
      offCross();
      unsubscribe();
    },
  };
}

"use client";

import { motionLimits } from "./motion";

type Neutral = { value: number; alpha: number };
type Interval = [number, number];
const contexts = new WeakMap<Document, CanvasRenderingContext2D>();

export function tabsColourScope(node: Element) {
  return node.closest<HTMLElement>('[data-slot="tabs-list"]');
}

/** A bounded proof of the named rendered regions, not a text/colour scanner.
 * Neutral endpoint intervals cover arbitrary relative clocks, including one
 * foreground settling on focus while a separate plate is still transitioning.
 * Unknown/final caller palettes are preserved through immediate cascade paint.
 */
export function tabsColourReadable(node: Element) {
  const list = tabsColourScope(node);
  if (!list) return false;
  if (node.getAttribute("data-slot") === "tabs-indicator" && node.getAttribute("data-variant") === "line") return true;
  const background = backdrop(list);
  if (!background) return false;
  const targets = Array.from(list.querySelectorAll<HTMLElement>('[data-slot="tabs-trigger"]'));
  if (targets.length > motionLimits.collectionVisuals) return false;
  const marker = list.querySelector<HTMLElement>('[data-slot="tabs-indicator"]');
  for (const trigger of targets) {
    if (tabsColourScope(trigger) !== list || (node.getAttribute("data-slot") === "tabs-trigger" && trigger !== node))
      continue;
    let surface = composite(colours(trigger, "background-color"), background);
    if (
      marker &&
      !marker.hidden &&
      marker.getAttribute("data-variant") !== "line" &&
      trigger.getAttribute("aria-selected") === "true"
    )
      surface = composite(colours(marker, "background-color"), background);
    const foreground = colours(trigger, "color");
    if (!surface || !foreground) return false;
    const ink = composite(foreground, surface);
    if (!ink || (ink[0] <= surface[1] && ink[1] >= surface[0])) return false;
    const luminance = (value: number) => (value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4);
    const low = ink[1] < surface[0] ? luminance(ink[1]) : luminance(surface[1]);
    const high = ink[1] < surface[0] ? luminance(surface[0]) : luminance(ink[0]);
    if ((high + 0.05) / (low + 0.05) < 4.5) return false;
  }
  return true;
}

function colours(node: Element, property: "background-color" | "color"): Neutral[] | null {
  const view = node.ownerDocument.defaultView;
  if (!view || typeof view.CanvasRenderingContext2D === "undefined") return null;
  let context = contexts.get(node.ownerDocument);
  if (!context) {
    const canvas = node.ownerDocument.createElement("canvas");
    canvas.width = canvas.height = 1;
    context = canvas.getContext("2d", { willReadFrequently: true }) ?? undefined;
    if (!context) return null;
    contexts.set(node.ownerDocument, context);
  }
  const values = [view.getComputedStyle(node).getPropertyValue(property)];
  const key = property === "color" ? "color" : "backgroundColor";
  for (const animation of node.getAnimations()) {
    if (!("transitionProperty" in animation) || animation.transitionProperty !== property) continue;
    for (const frame of (animation.effect as KeyframeEffect | null)?.getKeyframes() ?? [])
      if (typeof frame[key] === "string") values.push(frame[key]);
  }
  const result: Neutral[] = [];
  for (const value of new Set(values)) {
    if (!view.CSS.supports("color", value)) return null;
    context.clearRect(0, 0, 1, 1);
    context.fillStyle = value;
    context.fillRect(0, 0, 1, 1);
    const [r = 0, g = 0, b = 0, a = 0] = context.getImageData(0, 0, 1, 1).data;
    if (a && Math.max(r, g, b) !== Math.min(r, g, b)) return null;
    result.push({ value: (r + g + b) / (3 * 255), alpha: a / 255 });
  }
  return result;
}
function composite(colours: Neutral[] | null, background: Interval | null): Interval | null {
  if (!colours?.length || (!background && colours.some((colour) => colour.alpha !== 1))) return null;
  const values = colours.flatMap(({ value, alpha }) =>
    (background ?? [0, 0]).map((base) => value * alpha + base * (1 - alpha)),
  );
  return [Math.min(...values), Math.max(...values)];
}
function backdrop(node: Element) {
  const ancestry: Element[] = [];
  for (let current: Element | null = node; current; current = current.parentElement) {
    if (ancestry.length >= motionLimits.collectionVisuals) return null;
    ancestry.push(current);
  }
  let interval: Interval | null = null;
  for (const current of ancestry.reverse()) {
    const values = colours(current, "background-color");
    if (!values) return null;
    if (!interval && values.every((value) => value.alpha === 0)) continue;
    interval = composite(values, interval);
    if (!interval) return null;
  }
  return interval;
}

